\section{Introduction}

\subsection{The experiment}
Let $f\in\mathbb Z[x]$ be irreducible with splitting field $K$ and Galois group $G$. For a prime $p$ not dividing the discriminant, the factorisation pattern of $f\bmod p$ (its \emph{splitting type}) is determined by the cycle type of the Frobenius class $\mathrm{Frob}_p\in G$. Chebotarev's density theorem makes these classes equidistributed. For a modulus $m$, the residue $p\bmod m$ sees part of $\mathrm{Frob}_p$, namely its image in a cyclotomic quotient. A natural statistic is therefore the \emph{type channel}: the empirical mutual information, over a finite sample of primes, between the residue $p\bmod m$ and the splitting type.

For $f=x^2-3$ (discriminant $12$, ramified primes $\{2,3\}$) quadratic reciprocity shows that for $p\neq2,3$ the polynomial splits mod $p$ if $p\equiv\pm1\pmod{12}$ and is inert if $p\equiv\pm5\pmod{12}$. Dirichlet's theorem then gives an ideal channel of exactly $1$ bit for the modulus $m=12$. The experiment found $I=1.0000$ bits on unramified primes only and $I=1.0020$ bits on all primes, including $2$ and $3$.

Two primes among thousands shift the channel by $+0.002$ bits. The routine practice of discarding ramified primes therefore needs a justification that does not depend on the specific polynomial, modulus or sample. This paper supplies one.

\subsection{Results in brief}
Writing $N=|U\cup R|$ and $r=|R|$, the main results are:
\begin{enumerate}
\item \textbf{Exact decomposition} (Theorem~\ref{thm:decomp}): $NI_{U\cup R}-|U|I_U-rI_R=E-D(g)-D(k)+D(k,g)$. Here $E$ is a mixing term and $D$ denotes the fibre defect.
\item \textbf{Ramified bracket} (Theorem~\ref{thm:bracket}): $|NI_{U\cup R}-|U|I_U-rI_R|\le2r(\log_2N+1/\ln2)$.
\item \textbf{Negligibility} (Theorem~\ref{thm:main}): $|I_{U\cup R}-I_U|\le\frac rN(3\log_2N+2/\ln2)$, for all read-outs.
\item \textbf{Asymptotic exclusion} (Corollary~\ref{cor:asym}) and the \textbf{certified regime} (Corollary~\ref{cor:two}): $r\le2$ and $N\ge2^{16}$ give a change of at most $0.002$ bits.
\item \textbf{Sharpness} (Theorem~\ref{thm:sharp}): the gain can be at least $\frac rN\log_2N$.
\item \textbf{Galois transfer} (Theorem~\ref{thm:galois}): a contaminated Chebotarev fibre product lies within the same bound of the Galois channel $I(\sigma;T)$.
\end{enumerate}
All results are statements about finite sets and counting measures. They apply verbatim to any dataset containing a small number of exceptional records.

\section{The counting channel and fibre log-sums}

Throughout, $\log_2$ is the binary logarithm, extended by $\log_20=0$. A \emph{sample} is a finite set $S$, and a \emph{read-out} is any function from $S$ to some set of labels.

\begin{definition}[Counting entropies]
Let $S$ be a nonempty sample with $|S|=N$, and let $g,k$ be read-outs. Under the uniform probability on $S$, let $H_S(g)=-\sum_v\frac{c_v}{N}\log_2\frac{c_v}{N}$, where $c_v=|\{x\in S:g(x)=v\}|$. Let $H_S(g\mid k)=H_S(k,g)-H_S(k)$, where $(k,g)$ is the paired read-out $x\mapsto(k(x),g(x))$. The \emph{counting mutual information}, or \emph{counting channel}, is
\[ I_S(g;k)=H_S(g)-H_S(g\mid k). \]
For the empty sample all three quantities are set to $0$.
\end{definition}

\begin{definition}[Fibre log-sum]
For a sample $S$ and a read-out $f$,
\[\Lambda_S(f)=\sum_{a\in S}\log_2\bigl|\{x\in S:f(x)=f(a)\}\bigr|=\sum_v c_v\log_2c_v\ \ge 0,\]
where $c_v$ is the size of the fibre $f^{-1}(v)\cap S$.
\end{definition}

\begin{lemma}[Entropies as fibre log-sums]\label{lem:lam}
For nonempty $S$ with $|S|=N$:
\begin{enumerate}
\item $H_S(g)=\log_2N-\Lambda_S(g)/N$;
\item $H_S(g\mid k)=(\Lambda_S(k)-\Lambda_S(k,g))/N$;
\item $N\,I_S(g;k)=N\log_2N-\Lambda_S(g)-\Lambda_S(k)+\Lambda_S(k,g)$.
\end{enumerate}
The identity in (3) also holds for $S=\varnothing$, where both sides vanish.
\end{lemma}
\begin{proof}
For (1), expand $-\sum_v\frac{c_v}N(\log_2c_v-\log_2N)$ and use $\sum_vc_v=N$. For the paired read-out, $\Lambda_S(k,g)=\sum_c\sum_vn_{cv}\log_2n_{cv}$ with $n_{cv}=|\{x\in S:k(x)=c,\ g(x)=v\}|$, where the sum runs over the product of the images and absent pairs contribute $0$. Applying (1) to $(k,g)$ and to $k$ and subtracting gives (2). Then (3) is (1) minus (2), multiplied by $N$.
\end{proof}

\begin{definition}[Fibre defect]
For disjoint samples $U,R$ and a read-out $f$ on $U\cup R$, put $D(f)=\Lambda_{U\cup R}(f)-\Lambda_U(f)-\Lambda_R(f)$.
\end{definition}

\begin{lemma}\label{lem:Dge}
$D(f)\ge0$.
\end{lemma}
\begin{proof}
Split $\Lambda_{U\cup R}(f)$ into the sums over $a\in U$ and over $a\in R$. Each fibre in $U\cup R$ contains the corresponding nonempty fibre in $U$ (respectively $R$), so the comparison follows term by term from the monotonicity of $\log_2$.
\end{proof}

\begin{lemma}\label{lem:logadd}
For $u>0$ and $\rho\ge0$, $\log_2(u+\rho)\le\log_2u+\dfrac{\rho}{u\ln2}$.
\end{lemma}
\begin{proof}
Apply $\ln t\le t-1$ with $t=(u+\rho)/u$, then divide by $\ln2$.
\end{proof}

\begin{lemma}[Amortised ratio sum]\label{lem:ratio}
For disjoint finite $U,R$ and any read-out $f$,
\[\sum_{a\in U}\frac{|\{x\in R:f(x)=f(a)\}|}{|\{x\in U:f(x)=f(a)\}|}\le|R|.\]
\end{lemma}
\begin{proof}
Group by $v=f(a)\in f(U)$. The $u_v$ terms with value $v$ each equal $\rho_v/u_v$, so together they contribute $\rho_v=|f^{-1}(v)\cap R|$. These sets are disjoint subsets of $R$.
\end{proof}

\begin{lemma}[Upper bound on the defect]\label{lem:Dle}
With $N=|U\cup R|$, $D(f)\le|R|\bigl(\log_2N+1/\ln2\bigr)$.
\end{lemma}
\begin{proof}
\emph{Unramified points.} For $a\in U$ let $u_a\ge1$ be the size of its fibre in $U$ and $\rho_a$ the size of its fibre in $R$. Its fibre in $U\cup R$ has size $u_a+\rho_a$. By Lemma~\ref{lem:logadd}, $\log_2(u_a+\rho_a)\le\log_2u_a+\rho_a/(u_a\ln2)$. Summing over $U$ and using Lemma~\ref{lem:ratio}, the $U$-part of $\Lambda_{U\cup R}(f)$ is at most $\Lambda_U(f)+|R|/\ln2$.

\emph{Ramified points.} For $a\in R$ the fibre in $U\cup R$ has size at most $N$, while the logarithm of the fibre in $R$ is nonnegative. Hence the $R$-part is at most $\Lambda_R(f)+|R|\log_2N$.
\end{proof}

\begin{remark}
A fibre of size $u$ that receives $\rho$ intruders pays about $\rho/u$ per member, so $\rho/\ln 2$ in total. Summed over all fibres this is $|R|/\ln2$, \emph{independent of $N$}. Only the intruders themselves can cost as much as $\log_2N$ each.
\end{remark}

\section{The exact ramified decomposition}

\begin{definition}[Mixing term]
For $u,r\in\mathbb N$ put $E(u,r)=(u+r)\log_2(u+r)-u\log_2u-r\log_2r$. For $u+r>0$ this equals $(u+r)\,h\bigl(\frac r{u+r}\bigr)$, where $h$ is the binary entropy function.
\end{definition}

\begin{lemma}[Mixing bounds]\label{lem:mix}
$0\le E(u,r)\le r\bigl(\log_2(u+r)+1/\ln2\bigr)$.
\end{lemma}
\begin{proof}
The lower bound follows from monotonicity of $\log_2$. For the upper bound, Lemma~\ref{lem:logadd} gives $u\log_2(u+r)\le u\log_2u+r/\ln2$ when $u>0$, and the case $u=0$ is trivial. Combine this with $r\log_2r\ge0$.
\end{proof}

\begin{theorem}[Exact ramified decomposition]\label{thm:decomp}
For finite samples $U,R$ and read-outs $g,k$,
\[
|U\cup R|\,I_{U\cup R}-|U|\,I_U-|R|\,I_R=\bigl(|U\cup R|\log_2|U\cup R|-|U|\log_2|U|-|R|\log_2|R|\bigr)-D(g)-D(k)+D(k,g),
\]
where every $I$ is evaluated at $(g;k)$. When $U$ and $R$ are disjoint, the first bracket is $E(|U|,|R|)$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:lam}(3) to $U\cup R$, $U$ and $R$, and subtract.
\end{proof}

\begin{theorem}[The ramified bracket]\label{thm:bracket}
If $U\cap R=\varnothing$ and $N=|U\cup R|$, then for all read-outs $g,k$,
\[\bigl|NI_{U\cup R}(g;k)-|U|I_U(g;k)-|R|I_R(g;k)\bigr|\le2|R|\Bigl(\log_2N+\frac1{\ln2}\Bigr).\]
\end{theorem}
\begin{proof}
Let $B=|R|(\log_2N+1/\ln2)$. By Lemmas~\ref{lem:Dge}, \ref{lem:Dle} and~\ref{lem:mix}, each of $E,D(g),D(k),D(k,g)$ lies in $[0,B]$. The right-hand side of Theorem~\ref{thm:decomp} is therefore at most $E+D(k,g)\le2B$ and at least $-D(g)-D(k)\ge-2B$.
\end{proof}

\section{Negligibility of the ramified contribution}

\begin{lemma}\label{lem:range}
For samples $S\subseteq T$ and read-outs $g,k$: $0\le I_S(g;k)\le H_S(g)\le\log_2|S|\le\log_2|T|$.
\end{lemma}
\begin{proof}
These are the standard facts that mutual information is nonnegative, conditional entropy is nonnegative, and entropy on at most $|S|$ atoms is at most $\log_2|S|$.
\end{proof}

\begin{theorem}[Ramified contribution is negligible]\label{thm:main}
Let $U,R$ be disjoint finite samples with $N=|U\cup R|$. For every pair of read-outs $g,k$,
\[\bigl|I_{U\cup R}(g;k)-I_U(g;k)\bigr|\le\frac{|R|}{N}\Bigl(3\log_2N+\frac2{\ln2}\Bigr).\]
\end{theorem}
\begin{proof}
If $N=0$ there is nothing to prove. Otherwise
\[N(I_{U\cup R}-I_U)=\bigl(NI_{U\cup R}-|U|I_U-|R|I_R\bigr)+|R|(I_R-I_U).\]
The first summand is bounded by $2|R|(\log_2N+1/\ln2)$ (Theorem~\ref{thm:bracket}). By Lemma~\ref{lem:range}, $I_R,I_U\in[0,\log_2N]$, so the second summand is at most $|R|\log_2N$ in absolute value. Add and divide by $N$.
\end{proof}

\begin{definition}[Ramified bound]
$\Bnd(r,N)=\dfrac rN\Bigl(3\log_2N+\dfrac2{\ln2}\Bigr)$. Since $\Bnd$ is monotone in $r$, Theorem~\ref{thm:main} gives $|I_{U\cup R}-I_U|\le\Bnd(r,N)$ whenever $|R|\le r$.
\end{definition}

\begin{corollary}[Exclusion is asymptotically justified]\label{cor:asym}
For each fixed $r$, $\Bnd(r,N)\to0$ as $N\to\infty$. Hence for every $r\in\mathbb N$ and $\varepsilon>0$ there is $N_0$ such that, for all disjoint $U,R$ with $|R|\le r$ and $|U\cup R|\ge N_0$, and all read-outs $g,k$, we have $|I_{U\cup R}(g;k)-I_U(g;k)|\le\varepsilon$.
\end{corollary}
\begin{proof}
We have $\Bnd(r,N)=r\bigl(\frac3{\ln2}\frac{\ln N}N+\frac2{\ln2}\frac1N\bigr)$, and $\ln N/N\to0$.
\end{proof}

\begin{corollary}[The certified two-prime regime]\label{cor:two}
If $|R|\le2$ and $|U\cup R|\ge2^{16}$, then $|I_{U\cup R}(g;k)-I_U(g;k)|\le0.002$ for all read-outs.
\end{corollary}
\begin{proof}
Let $x=N\ge65536$. Lemma~\ref{lem:logadd} with $u=65536$ gives $\log_2x\le16+(x-65536)/(65536\ln2)$. Hence
\[\Bnd(2,x)\le\frac{96}x+\frac6{65536\ln2}-\frac2{x\ln2}\le\frac{96}{65536}+\frac6{65536\cdot0.6931471803}<0.0016,\]
using $\ln2>0.6931471803$.
\end{proof}

\subsection{Comparison with the data}
For $x^2-3$ with modulus $12$ and the sample of all primes $p\le X$:
\begin{center}
\begin{tabular}{rrrrrrr}
\toprule
$X$ & $N$ & $I$ (all) & $I$ (unram.) & gap & $\Bnd(2,N)$ & gap$/\Bnd$\\
\midrule
$10^3$ & 168 & 1.0787 & 0.9974 & $+0.0813$ & 0.2984 & 0.27\\
$10^4$ & 1229 & 1.0157 & 0.9999 & $+0.0158$ & 0.0548 & 0.29\\
$10^5$ & 9592 & 1.0026 & 1.0000 & $+0.0026$ & 0.0089 & 0.30\\
$10^6$ & 78498 & 1.0004 & 1.0000 & $+0.0004$ & 0.0013 & 0.30\\
\bottomrule
\end{tabular}
\end{center}
The experimental $+0.002$ bits corresponds to samples of about $10^4$ primes. The ratio settles near $0.3$: the rate $\log N/N$ is attained, and the true constant is about one third of the proved constant $3$.

The gap is positive here for a simple reason. The primes $2$ and $3$ occupy residue classes no unramified prime uses, and they carry the new type ``ramified''. These new residues determine the type completely, so the type entropy rises by about $h(2/N)$ while the conditional entropy stays $0$.

\section{Sharpness of the rate}

\begin{theorem}[Sharpness]\label{thm:sharp}
For all $r\le n$ there are disjoint $U,R\subset\mathbb N$ with $|R|=r$ and $|U\cup R|=n$, and a read-out $T$, such that
\[I_{U\cup R}(T;T)-I_U(T;T)\ge\frac rn\log_2n.\]
\end{theorem}
\begin{proof}
Let $u=n-r$, $U=\{0,\dots,u-1\}$ and $R=\{u,\dots,n-1\}$. Define $T(x)=0$ for $x<u$ and $T(x)=x+1$ for $x\ge u$. Then $I_S(T;T)=H_S(T)$ for every $S$. On $U$ the type is constant, so $H_U(T)=0$. On $U\cup R$ the fibres are $U$ and $r$ singletons, so $\Lambda_{U\cup R}(T)=u\log_2u$ and
\[H_{U\cup R}(T)=\log_2n-\frac un\log_2u\ge\log_2n-\frac un\log_2n=\frac rn\log_2n.\qedhere\]
\end{proof}
Hence the $\log_2N$ factor in Theorem~\ref{thm:main} cannot be removed, and the bound is optimal up to the leading constant ($3$ versus $1$).

\section{Transfer to the Chebotarev fibre product}

Let $G$ be a finite group, $T:G\to\mathcal T$ a type map, and $\sigma:G\to\Delta$ the map recording what a residue class sees of a group element. The \emph{Galois channel} is $I_G(\sigma;T)$, the mutual information under the uniform law on $G$.

\begin{definition}[Balanced fibre product]
Let $A$ be a finite set of residue data with $\chi:A\to\Delta$, and let $U_0\subseteq A$. Put
\[\Fp=\{(a,h)\in U_0\times G:\chi(a)=\sigma(h)\},\]
with read-outs $(a,h)\mapsto a$ and $(a,h)\mapsto T(h)$. The fibre product is \emph{balanced with multiplicity $K>0$} if $|\{a\in U_0:\chi(a)=\sigma(h)\}|=K$ for every $h\in G$.
\end{definition}

For a balanced fibre product, the second coordinate is uniform on $G$. Given the first coordinate $a$, the second is uniform on $\sigma^{-1}(\chi(a))$. Hence $I_\Fp(T\circ\mathrm{pr}_2;\mathrm{pr}_1)=I_G(\sigma;T)$.

\begin{theorem}[Galois channel with ramified contamination]\label{thm:galois}
Let $\Fp$ be balanced with multiplicity $K>0$, and let $R\subseteq A\times G$ be disjoint from $\Fp$ with $|R|\le r$. Then, with $N=|\Fp\cup R|$,
\[\bigl|I_{\Fp\cup R}(T\circ\mathrm{pr}_2;\mathrm{pr}_1)-I_G(\sigma;T)\bigr|\le\Bnd(r,N).\]
\end{theorem}
\begin{proof}
Replace $I_G(\sigma;T)$ by $I_\Fp$ and apply Theorem~\ref{thm:main} with $U=\Fp$.
\end{proof}

\section{Algorithms}
\textbf{Algorithm A (counting channel).} Build count tables for $g$, $k$ and $(k,g)$, compute $\Lambda(f)=\sum c\log_2c$, and return $\log_2N-(\Lambda(g)+\Lambda(k)-\Lambda(k,g))/N$. This takes $O(N)$ expected time.

\textbf{Algorithm B (exclusion certificate).} Given $N,r,\varepsilon$, certify exclusion if $\Bnd(r,N)\le\varepsilon$. Otherwise find the least admissible $N_0$ by doubling and bisection, which takes $O(\log N_0)$ operations.

\textbf{Algorithm C (extremal configuration).} Evaluate the closed form $\log_2n-\frac{n-r}n\log_2(n-r)$.

\section{Discussion}
\textbf{The constant.} Let $Z$ be the indicator of $R$ and $\varepsilon=r/N$. One checks that $D(f)=N\bigl(h(\varepsilon)-I(f;Z)\bigr)$, hence
\[NI_{U\cup R}-|U|I_U-rI_R=N\bigl[I(g;Z)-I(g;Z\mid k)\bigr],\]
with both terms bounded by $Nh(\varepsilon)$. This removes one defect from the bracket. It is consistent with the observed ratio of about $1/3$, and it is the starting point for improving the constant.

\textbf{Beyond primes.} Theorem~\ref{thm:main} applies to any labelled dataset. Removing $r$ arbitrary outliers from $N$ records changes any plug-in mutual information by at most $\Bnd(r,N)$, and by Theorem~\ref{thm:sharp} this worst case is genuinely of order $\frac rN\log N$.

\section{Future work}
\begin{enumerate}
\item \emph{Sharp constant:} prove $\sup|I_{U\cup R}-I_U|=\frac rN\log_2N\,(1+o(1))$ for fixed $r$.
\item \emph{Full Chebotarev spectrum:} show that the empirical channel over all $p\le X$ converges to $I_G(\sigma;T)$ with error $O_K(\log\log X/\log X)$ from ramification plus the Chebotarev error term.
\item \emph{Capacity-defect inequality:} prove $I_{U\cup R}-I_U\le h(r/N)+\frac rN(I_R-I_U)$, with equality exactly for disjoint ramified types and residues.
\end{enumerate}

\section{Conclusion}
A small set of exceptional points moves an empirical mutual information on $N$ points by $O(\frac rN\log N)$ bits. The explicit constant is $\frac rN(3\log_2N+2/\ln2)$, and the $\log N$ factor is unavoidable. For $x^2-3$ the two ramified primes contribute the observed $+0.002$ bits, well inside the bound. Excluding ramified primes is fully justified.

