from __future__ import annotations
import math
from collections import Counter


def extremal_type(u: int, x: int) -> int:
    """Unramified indices (< u) share type 0; ramified indices get private types."""
    return 0 if x < u else x + 1


def entropy_bits(labels: list[int]) -> float:
    n = len(labels)
    return 0.0 if n == 0 else -sum(c / n * math.log2(c / n) for c in Counter(labels).values())


def extremal_gain(n: int, r: int) -> tuple[float, float, float]:
    """Return (gain by direct counting, closed form, lower bound (r/n) log2 n)."""
    u = n - r
    full = [extremal_type(u, x) for x in range(n)]
    gain = entropy_bits(full) - entropy_bits(full[:u])   # I(T;T) = H(T)
    closed = math.log2(n) - (u / n) * math.log2(u) if u > 0 else math.log2(n)
    return gain, closed, r / n * math.log2(n)


if __name__ == "__main__":
    for n, r in [(100, 1), (10_000, 2), (100_000, 5)]:
        print(n, r, extremal_gain(n, r))
